import { assertOutputFormat } from './output.mjs'

export const SUPPORTED_PBKDF2 = ['sha256', 'sha384', 'sha512'] // SHA-2, all webcrypto-compatible
export const SUPPORTED_HMAC = ['sha256', 'sha384', 'sha512'] // SHA-2, all webcrypto-compatible
export const SUPPORTED_HASH = [
  ...['sha224', 'sha256', 'sha384', 'sha512', 'sha512-256'], // SHA-2
  ...['sha3-256', 'sha3-384', 'sha3-512'], // SHA-3
  ...['keccak256', 'keccak512'], // keccak
  ...['blake256'], // blake1
  ...['blake2b160', 'blake2b192', 'blake2b224', 'blake2b256', 'blake2b512'], // blake2b
  ...['blake2b-4bytes', 'blake2b-5bytes'], // blake2b checksums
  ...['ripemd160', 'hash160', 'p2sh-hash160'],
]

export function assertHashType(type, supported) {
  // NOTE: this has to be in sync with other places where type is used
  if (!supported.includes(type)) throw new TypeError('Unsupported hash type')
}

export function assertHashParams(type, form) {
  assertHashType(type, SUPPORTED_HASH)
  assertOutputFormat(form)
}

export function assertHmacParams(type, secret, form) {
  assertHashType(type, SUPPORTED_HMAC)
  assertOutputFormat(form)

  // This also covers Buffer as they are Uint8Array instances
  if (!(typeof secret === 'string' || secret instanceof Uint8Array)) {
    throw new Error('Unsupported hmac argument')
  }

  if (!(secret.length > 0)) {
    throw new Error('Zero-length key is not supported')
  }
}

const P2SH_OP_0 = Uint8Array.of(0x00, 0x14)

export function GET_P2SH_OP_0(data) {
  if (!(data instanceof Uint8Array)) throw new Error('p2sh hash requires an Uint8Array / Buffer')
  if (data.length !== 33 || (data[0] !== 2 && data[0] !== 3)) {
    // We don't verify point correctness here, just that the form looks like a public key -- this is not for security, but to
    // protect against accidentally feeding input in wrong form and generating invalid addresses
    // See https://bitcoincore.org/en/segwit_wallet_dev/#creation-of-p2sh-p2wpkh-address
    throw new Error('p2sh requires compressed public keys')
  }
  return P2SH_OP_0
}
